function queryRiskHistory(){$("#titleBack").click(function(){$("#titleBack").attr("href","javascript:redirectUrl('/WeixinService/business/user/riskLevelNew.shtml')")}),$(".header .top-a h2").html("历史测评记录"),loadRiskHistroy()}function loadRiskHistroy(){$.ajax({async:!1,url:"/WeixinService/business/queryUserRiskHistory.xhtml",dataType:"json",cache:!1,type:"POST",error:function(){show_tips("网络繁忙，请稍后再试。")},success:function(s){if(s){for(var i=s,e="",t=0;t<i.length;t++){var r=i[t];e+='<tr class="risk_tr">',e+='<td class="risk_td1">'+r.riskEvalDate+"</td>",e+='<td class="risk_td2">'+r.riskLevel+"</td></tr>"}$("#riskData").html(e)}}})}function backRiskPage(){window.location.href="/WeixinService/business/user/riskLevelNew.shtml"}